import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing } from '../remotionShim';
// Standard font loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};



export type BatteryEnergyProps = Record<string, any>;

const BatteryEnergy: React.FC<BatteryEnergyProps> = ({
  backgroundColor = "#1a1a1a",
  transparentBackground = false,
  durationInSeconds = 12,
  positiveColor = "#4ade80", // bright green
  negativeColor = "#f87171", // soft red
  batteryOutlineColor = "#ffffff",
  textColor = "#ffffff",
}) => {
  useFontLoader(["Montserrat"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  // -- LOGIC & TIMING --
  const fillers = ["Fitness", "Eating Well", "Family Time", "Meaningful Work"];
  const drainers = ["Negative People", "Unhealthy Habits", "Draining Work"];
  
  // Total slots: 4 fill + 1 pause + 3 drain = 8 slots
  const totalSlots = fillers.length + 1 + drainers.length;
  const slotDuration = durationInFrames / totalSlots;

  // Calculate current slot index
  const currentSlotIndex = Math.min(
    Math.floor(frame / slotDuration),
    totalSlots - 1
  );
  
  // Local frame within the current slot (0 to slotDuration)
  const localFrame = frame % slotDuration;

  // Determine State
  const isFilling = currentSlotIndex < fillers.length;
  const isPause = currentSlotIndex === fillers.length;
  const isDraining = currentSlotIndex > fillers.length;

  // -- BATTERY LEVEL CALCULATION --
  // We construct a continuous interpolation for the battery level
  // Points: [0, 1, 2, 3, 4, 5, 6, 7, 8] * slotDuration
  // Values: [0, .25, .5, .75, 1, 1, .66, .33, 0]
  
  const inputRanges = Array.from({ length: totalSlots + 1 }).map((_, i) => i * slotDuration);
  const outputRanges = [
    0,    // Start
    0.25, // Fill 1
    0.50, // Fill 2
    0.75, // Fill 3
    1.00, // Fill 4 (Full)
    1.00, // Pause (Still Full)
    0.66, // Drain 1
    0.33, // Drain 2
    0.00  // Drain 3 (Empty)
  ];

  const rawLevel = interpolate(frame, inputRanges, outputRanges, {
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.cubic), // Smooth fluid movement
  });

  // -- TEXT LABEL LOGIC --
  let currentText = "";
  let isPositive = true;

  if (isFilling) {
    currentText = fillers[currentSlotIndex];
    isPositive = true;
  } else if (isPause) {
    currentText = "Fully Charged!";
    isPositive = true;
  } else if (isDraining) {
    const drainIndex = currentSlotIndex - (fillers.length + 1);
    currentText = drainers[drainIndex];
    isPositive = false;
  }

  // Text Animation (Pop in and out per slot)
  const textEntrance = spring({
    frame: localFrame,
    fps,
    config: { damping: 12, stiffness: 100 },
  });
  
  const textExitStart = slotDuration - (fps * 0.5); // Start fading out 0.5s before end of slot
  const textOpacity = interpolate(
    localFrame,
    [0, 10, textExitStart, slotDuration],
    [0, 1, 1, 0],
    { extrapolateRight: "clamp" }
  );

  const textScale = interpolate(textEntrance, [0, 1], [0.5, 1]);

  // -- STYLES --
  const bgStyle = transparentBackground ? "transparent" : backgroundColor;
  
  const batteryWidth = width * 0.25;
  const batteryHeight = height * 0.5;
  const borderSize = width * 0.015;
  const nippleHeight = batteryHeight * 0.06;
  const nippleWidth = batteryWidth * 0.4;
  const cornerRadius = batteryWidth * 0.15;

  // Shake effect when draining
  const shake = isDraining ? Math.sin(frame * 0.5) * 5 : 0;

  return (
    <AbsoluteFill style={{ backgroundColor: bgStyle, fontFamily: "Montserrat", alignItems: "center", justifyContent: "center" }}>
      
      {/* Battery Nipple */}
      <div
        style={{
          position: "absolute",
          top: (height - batteryHeight) / 2 - nippleHeight + shake,
          width: nippleWidth,
          height: nippleHeight,
          backgroundColor: batteryOutlineColor,
          borderTopLeftRadius: cornerRadius / 2,
          borderTopRightRadius: cornerRadius / 2,
        }}
      />

      {/* Battery Body */}
      <div
        style={{
          position: "relative",
          width: batteryWidth,
          height: batteryHeight,
          border: `${borderSize}px solid ${batteryOutlineColor}`,
          borderRadius: cornerRadius,
          overflow: "hidden",
          backgroundColor: `${batteryOutlineColor}20`, // slight tint inside
          transform: `translateY(${shake}px)`,
        }}
      >
        {/* Liquid Fill */}
        <div
          style={{
            position: "absolute",
            bottom: 0,
            left: 0,
            right: 0,
            height: `${rawLevel * 100}%`,
            backgroundColor: isDraining ? negativeColor : positiveColor,
            transition: "background-color 0.5s ease", // CSS transition okay here for color blend or use interpolateColors
            boxShadow: `0 0 40px ${isDraining ? negativeColor : positiveColor}80`, // glow
          }}
        >
            {/* Bubbles / Texture overlay could go here */}
            <div style={{
                width: "100%", 
                height: "10px", 
                backgroundColor: "rgba(255,255,255,0.3)", 
                position: "absolute", 
                top: 0
            }}/>
        </div>

        {/* Percentage Label inside Battery */}
        <div style={{
            position: "absolute",
            width: "100%",
            top: "50%",
            transform: "translateY(-50%)",
            textAlign: "center",
            fontSize: batteryWidth * 0.25,
            fontWeight: 900,
            color: rawLevel > 0.5 ? "rgba(0,0,0,0.4)" : batteryOutlineColor,
            zIndex: 10,
        }}>
            {Math.round(rawLevel * 100)}%
        </div>
      </div>

      {/* Activity Text Label */}
      <div
        style={{
            position: "absolute",
            top: (height + batteryHeight) / 2 + 50, // Below battery
            width: width,
            textAlign: "center",
            opacity: textOpacity,
            transform: `scale(${textScale}) translateY(${shake}px)`,
        }}
      >
        <h1 style={{
            color: isPositive ? positiveColor : negativeColor,
            fontSize: width * 0.05,
            fontWeight: 700,
            margin: 0,
            textShadow: `0 4px 20px ${isPositive ? positiveColor : negativeColor}40`
        }}>
            {isPositive && !isPause ? "+ " : isDraining ? "- " : ""}{currentText}
        </h1>
      </div>

    </AbsoluteFill>
  );
};

export default BatteryEnergy;